CREATE TRIGGER RefStlScript_Version_Create
	ON RefStlScript
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT STL_PK, 'STL'
	FROM inserted
GO
CREATE TRIGGER RefStlScript_Version_Update
	ON RefStlScript
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON STL_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefStlScript_DataChangeHistory
	ON RefStlScript
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT STL_PK, 'STL' FROM inserted
	UNION
	SELECT STL_PK, 'STL' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefStlScript_DataProcessingResult_Delete
	ON RefStlScript
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.STL_PK
	END
GO
